INSERT INTO `email_templates` (`id`, `name`, `type`, `subject`, `message`, `created_at`, `updated_at`) VALUES
(1, 'New User', 'new_user', 'Welcome {user_name}', '<p>Hi {user_name},</p><p>Welcome to {company_name}. It\'s great to have you here!</p><p>Have a great time!</p><p>Regards,<br>{company_name} team</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13'),
(2, 'Edited Job', 'new_edited_job_available', 'New Edited Job Available For Approval!', '<p>Hello <strong>{admin_name}</strong>,<br>A new edited job available for approval!</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13'),
(3, 'New Job Available', 'new_job_available', 'New Job Available For Approval!', '<p>Hello {admin_name},<br>A new job available for approval!</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13'),
(4, 'New Plan Purchase', 'new_plan_purchase', '{user_name} Has Purchased The {plan_label} Plan!', '<p>{user_name} Has Purchased The {plan_label} Plan!</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13'),
(5, 'New User Registered', 'new_user_registered', 'New {user_role} Registered!', '<p>Hello {admin_name},<br>A {user_role} Registered Recently!</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13'),
(6, 'Plan Purchase', 'plan_purchase', 'Plan Purchased', '<p>Hello {user_name}!<br>You purchase of {plan_type} has been successfully completed!<br>Regards</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13'),
(7, 'New Pending Candidate', 'new_pending_candidate', 'Candidate Created', '<p>Hello {user_name},<br><br>Your candidate profile has been created and is waiting for admin approval.<br><br>Please login with your credentials below to check status -<br>Your Email : {user_email}<br>Your Password : {user_password}<br><br>Regards</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13'),
(8, 'New Candidate', 'new_candidate', 'Candidate Created', '<p>Hello {user_name},<br><br>Your candidate profile has been created.<br><br>Please login with your credentials below to check status -<br>Your Email : {user_email}<br>Your Password : {user_password}<br><br>Regards</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13'),
(9, 'New Company Pending', 'new_company_pending', 'Company created and waiting for admin approval', '<p>Hello {user_name},<br><br>Your company profile has been created and is waiting for admin approval.<br><br>Please check back your account with the login information below -<br>Your Email : {user_email}<br>Your Password : {user_password}<br><br>Regards</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13'),
(10, 'New Company', 'new_company', 'Company Created', '<p>Hello {user_name},<br><br>Your company profile has been created. Please login with below information.<br><br>Please check back your account with the login information below -<br>Your Email : {user_email}<br>Your Password : {user_password}<br><br>Regards</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13'),
(11, 'Update Company Password', 'update_company_pass', '{account_type} Updated', '<p>Hello {user_name},<br><br>Your {account_type} profile password updated.<br><br>Your Email : {user_email}<br>Your password : {password}<br><br>Regards</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13'),
(12, 'Verify Subscription Notification', 'verify_subscription_notification', 'Verify Your Subscription', '<p>Thanks for your interest in our newsletter!</p><p>You\'re one step away</p><h2>verify your email address</h2><p>to subscribe our newletter.</p><h3><a href=\'{verify_subscription}\'>Verify Now</a>&nbsp;</h3><p>Regards</p>', '2023-11-14 04:49:13', '2023-11-14 04:49:13');
